import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class T {
    static void t(String label, Object actual, Object expected) {
        boolean ok = expected.equals(actual);
        System.out.println((ok ? "PASS " : "FAIL ") + label + (ok ? "" : "\n  expected: " + expected + "\n  actual:   " + actual));
    }
    public static void main(String[] a) {
        // 1. RCDATA: start tags inside title are text
        Document d = Jsoup.parse("<title><b>bold</b> &amp; &#65;</title><p id=x>after");
        t("title text", d.title(), "<b>bold</b> & A");
        t("p sibling", d.select("p").size(), 1);
        t("p id", d.select("p").attr("id"), "x");

        // 2. case-insensitive end tag match
        d = Jsoup.parse("<TITLE>text</TITLE><p>after");
        t("title case", d.title(), "text");
        d = Jsoup.parse("<title>text</TITLE><p>after");
        t("title case2", d.title(), "text");
        d = Jsoup.parse("<Title>text</tItLe><p>after");
        t("title case3", d.title(), "text");

        // 3. textarea
        d = Jsoup.parse("<body><textarea><b>x</b>&#65;</textarea><p>after");
        t("textarea", d.select("textarea").text(), "<b>x</b>A");

        // 4. unterminated
        d = Jsoup.parse("<title>abc<div>def");
        t("unterminated title", d.title(), "abc<div>def");
        t("unterminated no extra nodes", d.body().childNodeSize(), 0);

        // 5. numeric refs
        t("zero", Jsoup.parse("<title>&#0;x</title>").title(), "�x");
        t("surrogate", Jsoup.parse("<title>&#xD800;x</title>").title(), "�x");
        t("out of range", Jsoup.parse("<title>&#x110000;x</title>").title(), "�x");
        t("max valid", Jsoup.parse("<title>&#x10FFFF;x</title>").title(), "􏿿x");
        t("hex X", Jsoup.parse("<title>&#X41;</title>").title(), "A");
        t("semicolonless", Jsoup.parse("<title>&#65b</title>").title(), "Ab");
        t("semicolonless hex", Jsoup.parse("<title>&#x41b</title>").title(), "Ab");
        t("invalid empty", Jsoup.parse("<title>&#;x</title>").title(), "&#;x");
        t("invalid hex empty", Jsoup.parse("<title>&#x;q</title>").title(), "&#x;q");
        t("invalid letter", Jsoup.parse("<title>&#z;y</title>").title(), "&#z;y");
        t("consecutive", Jsoup.parse("<title>&#65;&#z;&#66;</title>").title(), "A&#z;B");

        // 6. script/style raw
        d = Jsoup.parse("<script>&amp;&#65;<b></script><p>after");
        t("script raw", d.select("script").html(), "&amp;&#65;<b>");
        d = Jsoup.parse("<style>&amp;<b></style><p>after");
        t("style raw", d.select("style").html(), "&amp;<b>");

        // 7. lone angle brackets in RCDATA
        d = Jsoup.parse("<title>a < b > c</title>");
        t("lone brackets", d.title(), "a < b > c");

        // 8. reparse stability
        String html = Jsoup.parse("<title>a &#65; <b> &amp;</title><textarea>x&#x41;</textarea><script>&#65;</script>").html();
        String html2 = Jsoup.parse(html).html();
        t("reparse", html2, html);

        // 9. pre newline skip (#2616)
        t("pre lf", Jsoup.parse("<pre>\nhello</pre>").select("pre").text(), "hello");
        t("textarea lf", Jsoup.parse("<textarea>\nhello</textarea>").select("textarea").text(), "hello");
        t("pre crlf", Jsoup.parse("<pre>\r\nhello</pre>").select("pre").text(), "hello");
